import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { useEffect, useMemo, useRef, useState, useCallback } from 'react'
import { Container, CustomText } from '../../../../../../components'
import { SectionStyle } from '../../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../lang'
import { useGetOfflineQuoteDetail } from '../../../state/hooks/usePolicyState'
import { OfflineQuoteAdditionalInfoStyle } from './index.style'
import OfflineVehicleData from '../../../components/OfflineVehicleData'
import { getFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import { OFFLINE_FORM_DATA } from '../../../../../../constants/cookies'
import PolicyHolderMobileEmail from '../components/PolicyHolderMobileEmail'
import AccessoriesWithImage from '../../../../Application/components/AccessoriessWithImage'
import PolicyAttachments from '../../../components/PolicyAttachments'
import { MANUAL_ORDER } from '../../../../../../constants/pkgCode'
import { NEW_POLICY_NEW_CAR, NEW_POLICY_USED_CAR, VEHICLE_PHOTO_TYPE } from '../../../constants'
import PolicyVehicleImgs from '../../../components/PolicyVehicleImg'
import BottomBtn from '../../../../../../components/BottomBtn'
import { SEND_GOLD_ICON } from '../../../../../../images'

function OfflineQuoteAdditionInfoContainer ({ history, match }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const [offlineLocalData, setOfflineLocalData] = useState(getFromLocalStorageData(OFFLINE_FORM_DATA))
  const [{ offlineQuoteDetailData = {} }, offlineQuoteDetailReq] = useGetOfflineQuoteDetail()
  const [{ OFFLINE_QUOTE_DETAIL_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ offlineQuoteDetailStatus }, dispatchError] = useErrorContextValue()
  const [isManualPolicy, setIsManualPolicy] = useState(false)
  const [imgsError, setImgsError] = useState({})

  const vehicleDataRef = useRef(null)
  const errorAccessoryImages = {}
  const imagesRef = useRef({})
  const policyHolderDataRef = useRef(null)
  const accessoriesRef = useRef(null)
  const policyAttachmentRef = useRef(null)

  useEffect(() => {
    if (OFFLINE_QUOTE_DETAIL_LOADER === undefined) {
      offlineQuoteDetailReq({
        quoteId: urlParams.quoteId
      })
    }
  }, [offlineQuoteDetailReq, urlParams, OFFLINE_QUOTE_DETAIL_LOADER])

  useEffect(() => {
    function resetErrorKey (key) {
      dispatchError(resetError({
        [key]: undefined
      }))
    }
    if (offlineQuoteDetailStatus === 'success' && !offlineLocalData.id) {
      setIsManualPolicy(offlineQuoteDetailData.policy_details.protection_case === MANUAL_ORDER)
      imagesRef.current = {
        ...offlineQuoteDetailData.policy_details.images,
        ...offlineLocalData.images
      }
      setOfflineLocalData((offlineLocalData) => ({
        ...offlineQuoteDetailData.policy_details,
        ...offlineLocalData
      }))
      resetErrorKey('offlineQuoteDetailStatus')
    }
  }, [
    offlineQuoteDetailStatus, offlineQuoteDetailData,
    offlineLocalData, dispatchError
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        OFFLINE_QUOTE_DETAIL_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handlingVehicleImgs = useCallback((data, type) => {
    imagesRef.current = {
      ...imagesRef.current,
      ...data
    }
  }, [])

  const handleOverView = useCallback(async (e) => {
    const isVehicleImgReq = [NEW_POLICY_NEW_CAR, NEW_POLICY_USED_CAR].includes(offlineLocalData?.protection_type?.code)
    let body = {
      images: {
        ...imagesRef.current
      },
      isManualPolicy
    }
    let isDataValid = true
    const policyHolderData = await policyHolderDataRef.current.handleSubmit(e)
    const attachmentData = await policyAttachmentRef.current.handleSubmit(e)
    const accessoriesData = accessoriesRef.current && accessoriesRef.current.state.accessories

    if (isManualPolicy) {
      const vehicleData = await vehicleDataRef.current.handleSubmit(e) || {}
      if (vehicleData && vehicleData.error) {
        const errorMap = vehicleData.error || {}
        for (const key in errorMap) {
          if (errorMap[key]) {
            isDataValid = false
            break
          }
        }
      }
      body = {
        ...body,
        ...vehicleData
      }
    }
    if (policyHolderData) {
      body = {
        ...body,
        ...policyHolderData
      }
    } else {
      isDataValid = false
    }
    if (attachmentData) {
      body = {
        ...body,
        ...attachmentData
      }
    }
    const imgError = {}
    let isValid = true
    if ((isVehicleImgReq && isManualPolicy) || (body.images && !!Object.keys(body.images).length)) {
      for (const value of VEHICLE_PHOTO_TYPE) {
        if (!body.images[value]) {
          isValid = false
          imgError[value] = true
        }
      }
    } else if (!isManualPolicy && isVehicleImgReq && (attachmentData === undefined)) {
      isDataValid = false
    }
    if (!isDataValid) {
      return
    }
    if (!isValid) {
      setImgsError(imgError)
      return
    }

    if (accessoriesData) {
      body.accessories = [...accessoriesData]
    }
    setToLocalStorage(OFFLINE_FORM_DATA, {
      ...body
    })
    history.push(`/offline/quotes/additional/info/${urlParams.quoteId}/preview`)
  }, [isManualPolicy, history, urlParams, offlineLocalData])

  return (
    <Container
      title={LANG_STRINGS.additionalInfo}
      loader={OFFLINE_QUOTE_DETAIL_LOADER}
      hideBottomTabs
    >
      {
        offlineQuoteDetailData.id && offlineLocalData?.agent_code && (
          <OfflineQuoteAdditionalInfoStyle>
            <CustomText
              color={AgentColorPallette.darkCharcoal}
              size='13px'
              weight={700}
              padLeft='20px'
              padRight='20px'
              top='16px'
            >
              {LANG_STRINGS.someAdditionalInfoRequiredByProvider}
            </CustomText>
            {
              isManualPolicy && (
                <>
                  <SectionStyle>
                    <OfflineVehicleData
                      preFilledData={offlineLocalData}
                      protectionType={offlineLocalData?.protection_type?.code}
                      ref={vehicleDataRef}
                      isRequired
                    />
                  </SectionStyle>
                  <div className='separator' />
                </>
              )
            }
            {
              isManualPolicy && [NEW_POLICY_NEW_CAR, NEW_POLICY_USED_CAR].includes(offlineLocalData?.protection_type?.code) && (
                <>
                  <SectionStyle padTop='16px'>
                    <PolicyVehicleImgs
                      isVehicleImgRequired
                      onUpdateVehicleImg={handlingVehicleImgs}
                      images={offlineLocalData.images}
                      errorImages={imgsError}
                      preFilledData={offlineLocalData}
                    />
                  </SectionStyle>
                  <div className='separator' />
                </>
              )
            }
            <SectionStyle padTop='16px'>
              <PolicyAttachments
                isManualPolicy={isManualPolicy}
                protectionType={offlineLocalData?.protection_type?.code}
                preFilledData={offlineLocalData}
                ref={policyAttachmentRef}
                isAdditionalInfo
              />
            </SectionStyle>
            <div className='separator' />
            <PolicyHolderMobileEmail
              ref={policyHolderDataRef}
              preFilledData={offlineLocalData}
              padBtm={!offlineLocalData?.accessories?.length}
            />
            {
              !!offlineLocalData?.accessories?.length && (
                <>
                  <div className='separator' />
                  <SectionStyle padBtm='24%' padTop='16px'>
                    <CustomText
                      color={AgentColorPallette.black}
                      weight={800}
                      size='16px'
                      bottom='10px'
                    >
                      {LANG_STRINGS.additionalAccessories}
                    </CustomText>
                    <CustomText
                      color={AgentColorPallette.fontGrey}
                      size='10px'
                      bottom='18px'
                    >
                      {LANG_STRINGS.useThePersonalPhotos}
                    </CustomText>
                    <AccessoriesWithImage
                      errorAccessoryImages={errorAccessoryImages}
                      ref={accessoriesRef}
                      accessories={offlineLocalData.accessories}
                      name='policyOfflineAccessoriesData'
                      className='offline-accessories-card'
                      isBtmBorder
                    />
                  </SectionStyle>
                </>
              )
            }
            <BottomBtn
              title={LANG_STRINGS.overview}
              icon={SEND_GOLD_ICON}
              onClick={handleOverView}
            />
          </OfflineQuoteAdditionalInfoStyle>
        )
      }
    </Container>
  )
}

export default OfflineQuoteAdditionInfoContainer
