import { useMemo, forwardRef } from 'react'
import { SectionStyle } from '../../../../../../../commonStyle/index.style'
import { CustomText, InnerForm } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../../../lang'

function PolicyHolderMobileEmail ({ preFilledData, padBtm }, ref) {
  const customerData = useMemo(() => {
    return {
      fields: [
        {
          type: 'phone_number',
          label: LANG_STRINGS.customerPhone,
          placeholder: 'Nomor Handphone E.g., 08xxxxxxxxx',
          defaultValue: preFilledData?.customer_phone_no,
          className: 'customer-phone-input',
          name: 'customer_phone_no'
        },
        {
          type: 'email',
          label: LANG_STRINGS.emailAddress,
          placeholder: 'Alamat Email',
          defaultValue: preFilledData?.customer_email,
          name: 'customer_email'
        }
      ]
    }
  }, [preFilledData])

  return (
    <SectionStyle padTop='14px' padBtm={padBtm ? '24%' : ''}>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        bottom='10px'
      >
        {LANG_STRINGS.policyHolderNew}
      </CustomText>
      <InnerForm
        formData={customerData}
        ref={ref}
      />
    </SectionStyle>
  )
}

export default forwardRef(PolicyHolderMobileEmail)
